// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.storageimport android.content.Contextimport androidx.room.Roomimport androidx.room.RoomDatabaseimport androidx.sqlite.db.SupportSQLiteDatabaseimport com.roshan.persona.database.NousDatabaseimport com.roshan.persona.security.keystore.KeystoreManagerimport dagger.hilt.android.qualifiers.ApplicationContextimport timber.log.Timberimport java.io.Fileimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — SQLCipher Migration Manager (Module 12, Pillar 4). * * Strategy §12.4 — migrates a plain Room database to a SQLCipher-encrypted * Room database. The migration is **atomic**: * *   1. Create a new encrypted database file alongside the plain one. *   2. Open both databases (plain for read, encrypted for write). *   3. Walk every table, copy rows in batches of 500. *   4. Verify integrity (PRAGMA integrity_check on the new database). *   5. Atomically swap: rename plain DB to `.bak`, rename encrypted DB to *      the original name. If both renames succeed, delete `.bak`. * * If any step fails, the swap is rolled back and the plain DB remains active. * * ## Real Android APIs used * * | Operation | API | * |-----------|-----| * | Plain Room DB | `Room.databaseBuilder(context, dbClass, fileName)` (no SQLCipher) | * | Encrypted Room DB | `Room.databaseBuilder(...).openHelperFactory(SupportFactory(passphrase))` | * | SQLCipher passphrase | `net.sqlcipher.database.SupportFactory(byteArray)` | * | Per-table copy | `SupportSQLiteDatabase.query("SELECT * FROM ...")` → `INSERT` batch | * | Integrity check | `db.query("PRAGMA integrity_check")` | * * NOTE: In NOUS's actual deployment, [DatabaseModule.provideNousDatabase] * already wires SQLCipher at app start. This manager exists for: * *   1. **Migration of pre-existing installs** — users who installed NOUS *      before Module 12 shipped have a plain Room DB. On first launch of *      the security-enabled build, this manager migrates them. *   2. **Future re-keying** — when the user changes their app-lock PIN, *      we re-derive the SQLCipher passphrase and migrate to the new key. * * @see com.roshan.persona.database.di.DatabaseModule */@Singletonclass SqlCipherMigrationManager @Inject constructor(    @ApplicationContext private val context: Context,    private val keystoreManager: KeystoreManager,) {    /**     * Migrate a plain Room database to SQLCipher encryption.     *     * @param plainDbName the plain database file name (e.g., "nous.db").     * @param encryptedDbName the target encrypted database file name     *   (typically the same as [plainDbName] — we swap in place).     * @param passphraseKeyAlias the Keystore alias holding the SQLCipher     *   passphrase. The passphrase is encrypted with this Keystore key and     *   stored in EncryptedSharedPreferences.     * @return the [MigrationResult]. Never throws — all errors map to     *   [MigrationResult.Failed].     */    suspend fun migrate(        plainDbName: String = NousDatabase.DATABASE_NAME,        encryptedDbName: String = NousDatabase.DATABASE_NAME,        passphraseKeyAlias: String = PASSPHRASE_KEY_ALIAS,    ): MigrationResult {        val startNanos = System.nanoTime()        val plainFile = context.getDatabasePath(plainDbName)        val tempEncryptedFile = context.getDatabasePath("$encryptedDbName.enc.tmp")        // ─── Pre-flight checks ────────────────────────────────────────        if (!plainFile.exists()) {            // No plain DB → already migrated (or fresh install).            return MigrationResult.Success(rowsMigrated = 0, durationMs = 0)        }        // Get or generate the SQLCipher passphrase (32 random bytes,        // encrypted with Keystore, stored in EncryptedSharedPreferences).        val passphrase = getOrCreatePassphrase(passphraseKeyAlias) ?: return MigrationResult.Failed(            reason = "encryption_key_unavailable",            detail = "Failed to get/generate SQLCipher passphrase",        )        // ─── Stage 1: Create encrypted database ──────────────────────        try {            val supportFactory = net.sqlcipher.database.SupportFactory(passphrase)            val encryptedDb = Room.databaseBuilder(                context,                NousDatabase::class.java,                tempEncryptedFile.name,            )                .openHelperFactory(supportFactory)                .build()            // Force the encrypted DB to be created (empty schema).            encryptedDb.openHelper.writableDatabase.let { db ->                // Run a no-op transaction to trigger schema creation.                db.beginTransaction()                try {                    db.endTransaction()                } finally {                    // Already ended above; no-op.                }            }            // ─── Stage 2: Copy tables ─────────────────────────────────            val rowsCopied = copyAllTables(                plainFile = plainFile,                encryptedDb = encryptedDb.openHelper.writableDatabase,            )            // ─── Stage 3: Integrity check ─────────────────────────────            if (!verifyIntegrity(encryptedDb.openHelper.writableDatabase)) {                encryptedDb.close()                tempEncryptedFile.delete()                return MigrationResult.Failed(                    reason = "integrity_check_failed",                    detail = "Encrypted DB failed PRAGMA integrity_check",                )            }            encryptedDb.close()            // ─── Stage 4: Atomic swap ─────────────────────────────────            val backupFile = File("${plainFile.absolutePath}.bak")            if (backupFile.exists()) backupFile.delete()            if (!plainFile.renameTo(backupFile)) {                tempEncryptedFile.delete()                return MigrationResult.NeedsRetry(stage = "swap_rename_plain_to_bak")            }            if (!tempEncryptedFile.renameTo(plainFile)) {                // Rollback: restore the plain DB.                backupFile.renameTo(plainFile)                tempEncryptedFile.delete()                return MigrationResult.NeedsRetry(stage = "swap_rename_encrypted_to_plain")            }            // ─── Stage 5: Cleanup ─────────────────────────────────────            // Delete the WAL and SHM files for the old plain DB.            File("${plainFile.absolutePath}-wal").delete()            File("${plainFile.absolutePath}-shm").delete()            backupFile.delete()            val durationMs = (System.nanoTime() - startNanos) / 1_000_000            Timber.tag("NOUS.Security").i(                "SQLCipher migration succeeded: rows=%d, durationMs=%d",                rowsCopied, durationMs,            )            return MigrationResult.Success(rowsMigrated = rowsCopied, durationMs = durationMs)        } catch (e: Exception) {            Timber.tag("NOUS.Security").w(e, "SQLCipher migration crashed")            tempEncryptedFile.delete()            return MigrationResult.Failed(                reason = "unexpected_exception",                detail = e.message,            )        }    }    /**     * Copy all tables from the plain database to the encrypted database.     *     * Walks `sqlite_master` to enumerate tables, then for each table:     *   - `CREATE TABLE` on encrypted DB (schema already created by Room,     *     but we ensure it exists).     *   - `INSERT INTO ... SELECT * FROM ...` in batches of 500.     *     * Returns the total rows copied.     */    private fun copyAllTables(        plainFile: File,        encryptedDb: SupportSQLiteDatabase,    ): Long {        // Open the plain DB read-only via SQLite (no Room needed for read).        val plainDb = androidx.sqlite.db.framework.FrameworkSQLiteOpenHelperFactory()            .create(                configuration = androidx.sqlite.db.SupportSQLiteOpenHelper.Configuration.builder(context)                    .name(plainFile.absolutePath)                    .callback(object : androidx.sqlite.db.SupportSQLiteOpenHelper.Callback(                        NousDatabase.DATABASE_VERSION,                    ) {                        override fun onCreate(db: SupportSQLiteDatabase) { /* no-op — DB exists */ }                        override fun onUpgrade(                            db: SupportSQLiteDatabase,                            oldVersion: Int,                            newVersion: Int,                        ) { /* no-op */ }                        override fun onDowngrade(                            db: SupportSQLiteDatabase,                            oldVersion: Int,                            newVersion: Int,                        ) { /* no-op */ }                    })                    .build(),            )            .readableDatabase        var totalRows = 0L        try {            // Enumerate user tables (exclude sqlite_* internal tables).            val tables = mutableListOf<String>()            plainDb.query("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE 'android_%' AND name NOT LIKE 'room_%'").use { cursor ->                while (cursor.moveToNext()) {                    tables.add(cursor.getString(0))                }            }            for (table in tables) {                // Count rows in the plain table.                val count = plainDb.query("SELECT COUNT(*) FROM `$table`").use { c ->                    if (c.moveToFirst()) c.getLong(0) else 0L                }                if (count == 0L) continue                // Stream-copy rows. We use `INSERT INTO ... SELECT * FROM ...`                // but cross-database references aren't possible, so we                // read from plain and write to encrypted in batches.                val batchSize = 500                var offset = 0                while (offset < count) {                    val cursor = plainDb.query(                        "SELECT * FROM `$table` LIMIT $batchSize OFFSET $offset",                    )                    val columnCount = cursor.columnCount                    val columnNames = cursor.columnNames                    encryptedDb.beginTransaction()                    try {                        while (cursor.moveToNext()) {                            val placeholders = (0 until columnCount).joinToString(",") { "?" }                            val sqliteStatement = encryptedDb.compileStatement(                                "INSERT OR IGNORE INTO `$table` (${columnNames.joinToString(",") { "`$it`" }}) VALUES ($placeholders)",                            )                            for (i in 0 until columnCount) {                                when (cursor.getType(i)) {                                    android.database.Cursor.FIELD_TYPE_NULL ->                                        sqliteStatement.bindNull(i + 1)                                    android.database.Cursor.FIELD_TYPE_INTEGER ->                                        sqliteStatement.bindLong(i + 1, cursor.getLong(i))                                    android.database.Cursor.FIELD_TYPE_FLOAT ->                                        sqliteStatement.bindDouble(i + 1, cursor.getDouble(i))                                    android.database.Cursor.FIELD_TYPE_STRING ->                                        sqliteStatement.bindString(i + 1, cursor.getString(i))                                    android.database.Cursor.FIELD_TYPE_BLOB ->                                        sqliteStatement.bindBlob(i + 1, cursor.getBlob(i))                                }                            }                            sqliteStatement.executeInsert()                            sqliteStatement.close()                            totalRows++                        }                        encryptedDb.setTransactionSuccessful()                    } finally {                        encryptedDb.endTransaction()                    }                    cursor.close()                    offset += batchSize                }            }        } finally {            plainDb.close()        }        return totalRows    }    /**     * Verify the encrypted database's integrity via PRAGMA integrity_check.         */    private fun verifyIntegrity(db: SupportSQLiteDatabase): Boolean {        return db.query("PRAGMA integrity_check").use { cursor ->            cursor.moveToFirst() && cursor.getString(0) == "ok"        }    }    /**     * Get or generate the SQLCipher passphrase.     *     * The passphrase is 32 random bytes, encrypted with [KeystoreManager]     * under [PASSPHRASE_KEY_ALIAS], stored in EncryptedSharedPreferences.     * On first call, generates a new passphrase and persists it. On     * subsequent calls, returns the existing passphrase.     */    private fun getOrCreatePassphrase(alias: String): ByteArray? {        // Check if we already have a passphrase stored.        val prefs = context.getSharedPreferences(PASSPHRASE_PREFS, Context.MODE_PRIVATE)        val existingCiphertext = prefs.getString(KEY_PASSPHRASE_CIPHERTEXT, null)        val existingIv = prefs.getString(KEY_PASSPHRASE_IV, null)        if (existingCiphertext != null && existingIv != null) {            // Decrypt the existing passphrase.            val ciphertext = com.roshan.persona.security.keystore.Ciphertext(                ivBase64 = existingIv,                ciphertextBase64 = existingCiphertext,                securityLevel = keystoreManager.lastSecurityLevel(alias),            )            val decrypted = keystoreManager.decryptString(alias, ciphertext) ?: return null            return android.util.Base64.decode(decrypted, android.util.Base64.NO_WRAP)        }        // Generate a new 32-byte random passphrase.        val randomBytes = ByteArray(32).also { java.security.SecureRandom().nextBytes(it) }        val b64 = android.util.Base64.encodeToString(randomBytes, android.util.Base64.NO_WRAP)        val ciphertext = keystoreManager.encryptString(alias, b64) ?: return null        prefs.edit()            .putString(KEY_PASSPHRASE_CIPHERTEXT, ciphertext.ciphertextBase64)            .putString(KEY_PASSPHRASE_IV, ciphertext.ivBase64)            .apply()        return randomBytes    }    private companion object {        const val PASSPHRASE_KEY_ALIAS = "nous.sqlcipher.passphrase"        const val PASSPHRASE_PREFS = "nous_sqlcipher_key"        const val KEY_PASSPHRASE_CIPHERTEXT = "passphrase_ciphertext"        const val KEY_PASSPHRASE_IV = "passphrase_iv"    }}